<template>
  <div>
    <!-- 点云查看模态框：按需加载单个 PLY -->
    <PointCloudViewer
      v-if="showPlyModal"
      :url="rootUrl + plyPath"
      :path="plyPath"
      @close="closePlyModal">
    </PointCloudViewer>

    <!-- 放大图像模态框 -->
    <div v-if="showZoomModal" class="zoom-modal" @click.self="closeZoomModal">
      <div class="zoom-modal-content" @click.stop>
        <div class="zoom-modal-header">
          <h3>{{ zoomedImagePath }}</h3>
          <span class="zoom-hint">滚轮缩放 · 拖拽平移 · ←→切图 · 空格复制 · Esc关闭 · {{ zoomIndex + 1 }}/{{ processedPaths.length }}</span>
          <el-button class="close-btn" @click="closeZoomModal" icon="el-icon-close" circle></el-button>
        </div>
        <div class="zoom-modal-body" ref="zoomBody"
             @wheel.prevent="onZoomWheel"
             @mousedown="onZoomPanStart"
             @mousemove="onZoomPanMove"
             @mouseup="onZoomPanEnd"
             @mouseleave="onZoomPanEnd">
          <img :src="rootUrl + zoomedImagePath + `?timestamp=${timestamp}`"
               :alt="zoomedImagePath"
               class="zoomed-image"
               :style="zoomImageStyle"
               draggable="false"
               @mousemove="updateZoomTooltip"
               @mouseleave="closeZoomTooltip">
          <div ref="zoomTooltip" class="zoom-tooltip" v-show="showZoomTooltip">{{ zoomTooltipContent }}</div>
        </div>
        <div class="zoom-modal-footer">
          <el-button @click="zoomPrev" :disabled="zoomIndex <= 0">上一张</el-button>
          <el-button @click="zoomNext" :disabled="zoomIndex >= processedPaths.length - 1">下一张</el-button>
          <el-button @click="resetZoom">重置缩放</el-button>
          <el-button @click="closeZoomModal">关闭</el-button>
          <el-button @click="copyZoomedImagePath" type="primary">复制路径</el-button>
        </div>
      </div>
    </div>

    <main class="main" :style="{ paddingLeft: navWidth + 'px' }">
      <!-- 每个子目录独立分组展示：列表模式下每组一个 ImageList，单图模式下每组一个 ImageFlipper -->
      <template v-if="singleBrowseMode == 0">
        <div v-if="dirLoading" class="list-loading-banner">加载中...</div>
        <div id="path-and-image" v-for="group in groupedPaths" :key="group.dir">
          <ImageList
            :rootUrl="rootUrl"
            :srcDir="group.dir"
            :srcImagePaths="group.paths"
            :width="imageShowWidth"
            :timestamp="timestamp.toString()"
            :clickMode="clickMode"
            :annoPending="annoPending"
            @zoom="zoomImage"
            @open-ply="openPlyModal"
            @path-copied="onPathCopied"
            @annotate-click="onAnnotateClick">
          </ImageList>
        </div>
      </template>
      <template v-else>
        <div id="path-and-image" class="show-single-group" v-for="group in groupedPaths" :key="group.dir">
          <ImageFlipper
            :rootUrl="rootUrl"
            :srcDir="group.dir"
            :srcImagePaths="group.paths"
            :width="imageShowWidth"
            :timestamp="timestamp.toString()"
            :clickMode="clickMode"
            :annoPending="annoPending"
            @zoom="zoomImage"
            @open-ply="openPlyModal"
            @path-copied="onPathCopied"
            @annotate-click="onAnnotateClick">
          </ImageFlipper>
        </div>
      </template>

      <div>{{ errInfo }}</div>
    </main>

    <nav :style="{ width: navWidth + 'px' }">
      <div class="nav-resize" @mousedown.prevent="onNavResizeStart"></div>
      <div>
        <el-input v-model="srcDir" @keyup.enter.native="browseDir()" placeholder="展示该目录的图片" clearable></el-input>
      </div>

      <div class="filter-options">
        <div class="label">默认目录前缀</div>
        <el-input v-model="defaultPrefix" placeholder="/data/mck/mmsegmentation" clearable size="small"
                  @change="persistDefaultPrefix"></el-input>
        <div class="anno-hint">相对路径将自动拼到此前缀下</div>
      </div>

      <div>参与遍历的后缀名：</div>
      <div class="postfixes">
        <el-checkbox-group v-model="checkedPostfixes">
          <el-checkbox v-for="(item, index) in filenamePostfixes" :label="item" :key="index">{{ item }}</el-checkbox>
        </el-checkbox-group>
      </div>

      <div class="filter-options">
        <div class="label">路径筛选</div>
        <el-input v-model="nameInclude" placeholder="包含（子串）" clearable size="small"></el-input>
        <el-input v-model="nameExclude" placeholder="排除（子串）" clearable size="small"
                  style="margin-top: 4px;"></el-input>
      </div>

      <el-radio-group v-model="singleBrowseMode">
        <el-radio label='0'>列表展示全部图片</el-radio>
        <el-radio label='1'>单图切换浏览</el-radio>
      </el-radio-group>

      <div class="label-bar">
        <div class="label">图片显示宽度</div>
        <el-slider class="bar" v-model="imageShowWidth" :step="10" :max="1400" :min="10">
        </el-slider>
      </div>

      <div class="sort-options">
        <div class="label">图像排序方式</div>
        <el-radio-group v-model="sortMode">
          <el-radio label="path">自然序</el-radio>
          <el-radio label="random">随机乱序</el-radio>
        </el-radio-group>
      </div>

      <div class="sort-options">
        <div class="label">单击行为</div>
        <el-radio-group v-model="clickMode" @change="clearAnnoPending">
          <el-radio label="copy">复制路径</el-radio>
          <el-radio label="anno">拉框标注</el-radio>
        </el-radio-group>
      </div>
      <div v-if="clickMode === 'anno'" class="filter-options">
        <div class="label">标注类别</div>
        <el-input v-model="annoLabel" placeholder="object" size="small" clearable></el-input>
        <div class="anno-hint">点两个对角保存 labelme json；Esc 取消当前点</div>
      </div>

      <el-button ref="preview" @click="browseDir" type="primary">预览</el-button>

      <div class="history">
        <el-tag class="history-tag" v-for="dir in historyDirs" :key="dir" closable @close="RemoveHistoryItem(dir)">
          <span @click="clickHistory(dir)" class="history-dir">{{ dir }}</span>
        </el-tag>
      </div>
      <div class="info-for-clicked-image">
        <div style="pointer-events: none; user-select: none;">点击的图像路径 </div>
        {{ clickedImagePath }}
        <div style="pointer-events: none; user-select: none;">点击的图像名称 </div>
        {{ clickedImageName }}
      </div>
    </nav>
  </div>
</template>

<script>
import ImageList from './ImageList.vue'
import ImageFlipper from './ImageFlipper.vue'
import PointCloudViewer from './PointCloudViewer.vue'
import Clipboard from 'clipboard'

function basename(p) {
  const parts = p.replace(/\\/g, '/').split('/');
  return parts[parts.length - 1] || p;
}

function isPlyPath(p) {
  return /\.ply$/i.test(p || '');
}

function naturalCompare(a, b) {
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
}

// 历史路径持久化 key（localStorage）
const HISTORY_STORAGE_KEY = 'image-viewer-history-dirs';
const PREFIX_STORAGE_KEY = 'image-viewer-default-prefix';
const NAV_WIDTH_STORAGE_KEY = 'image-viewer-nav-width';
const NAV_WIDTH_DEFAULT = 320;
const NAV_WIDTH_MIN = 200;
const NAV_WIDTH_MAX = 640;

// 从 localStorage 读取历史路径，解析失败则忽略
function loadHistoryDirs() {
  try {
    const raw = localStorage.getItem(HISTORY_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter(d => typeof d === 'string') : [];
  } catch (e) {
    return [];
  }
}

function loadDefaultPrefix() {
  try {
    const v = localStorage.getItem(PREFIX_STORAGE_KEY);
    return typeof v === 'string' ? v : '';
  } catch (e) {
    return '';
  }
}

function loadNavWidth() {
  try {
    const n = parseInt(localStorage.getItem(NAV_WIDTH_STORAGE_KEY), 10);
    if (Number.isFinite(n)) {
      return Math.min(NAV_WIDTH_MAX, Math.max(NAV_WIDTH_MIN, n));
    }
  } catch (e) { /* ignore */ }
  return NAV_WIDTH_DEFAULT;
}

function joinPrefix(prefix, rel) {
  const p = (prefix || '').replace(/\/+$/, '');
  const r = (rel || '').replace(/^\/+/, '');
  if (!p) return rel;
  if (!r) return p;
  return p + '/' + r;
}

export default {
  name: 'ImageViewer',
  components: {
    ImageList,
    ImageFlipper,
    PointCloudViewer,
  },
  data() {
    return {
      rawDirFilePathsMap: {},
      srcDir: "",
      errInfo: "",
      rootUrl: "",
      filenamePostfixes: [".jpg", ".png", ".PNG", ".gif", ".JPG", ".bmp", ".BMP", ".jpeg", ".ply"],
      checkedPostfixes: [".jpg", ".png", ".PNG", ".gif", ".JPG", ".bmp", ".BMP", ".jpeg", ".ply"],
      singleBrowseMode: '0',
      imageShowWidth: 200,
      timestamp: "",
      historyDirs: loadHistoryDirs(),
      defaultPrefix: loadDefaultPrefix(),
      navWidth: loadNavWidth(),
      navResizing: false,
      sortMode: 'path',
      nameInclude: "",
      nameExclude: "",
      dirLoading: false,
      clickMode: "copy",
      annoLabel: "object",
      annoPending: null,

      clickedImagePath: "",
      clickedImageName: "",

      showZoomModal: false,
      zoomedImagePath: "",
      zoomIndex: 0,
      zoomScale: 1,
      zoomOffsetX: 0,
      zoomOffsetY: 0,
      zoomPanning: false,
      zoomPanLastX: 0,
      zoomPanLastY: 0,
      showZoomTooltip: false,
      zoomTooltipContent: "",

      showPlyModal: false,
      plyPath: "",
    };
  },
  computed: {
    // 全局扁平列表（供放大模态框跨目录翻页、总数统计使用）；排除 ply
    processedPaths() {
      return this.groupedPaths.reduce((acc, group) => {
        return acc.concat(group.paths.filter(p => !isPlyPath(p)));
      }, []);
    },
    // 按子目录分组：目录间自然序，组内按排序方式处理；全局扁平顺序见 processedPaths
    groupedPaths() {
      const include = (this.nameInclude || "").trim();
      const exclude = (this.nameExclude || "").trim();
      const groups = Object.keys(this.rawDirFilePathsMap)
        .sort(naturalCompare)
        .map(dir => {
          let paths = this.rawDirFilePathsMap[dir] || [];
          if (include || exclude) {
            // 路径筛选：子串匹配整个路径（包含/排除）
            paths = paths.filter(p => {
              if (include && !p.includes(include)) return false;
              if (exclude && p.includes(exclude)) return false;
              return true;
            });
          }
          paths = paths.slice();
          if (this.sortMode === 'random') {
            this.shuffleArray(paths);
          } else {
            paths.sort(naturalCompare);
          }
          return { dir, paths };
        })
        .filter(group => group.paths.length > 0);
      return groups;
    },
    zoomImageStyle() {
      return {
        transform: `translate(${this.zoomOffsetX}px, ${this.zoomOffsetY}px) scale(${this.zoomScale})`,
        cursor: this.zoomPanning ? 'grabbing' : 'grab',
      };
    },
  },
  watch: {
    // 历史路径变化即落盘，刷新后可恢复
    historyDirs: {
      deep: true,
      handler(val) {
        try {
          localStorage.setItem(HISTORY_STORAGE_KEY, JSON.stringify(val));
        } catch (e) { /* 存储不可用时静默降级 */ }
      },
    },
    sortMode() {
      // 分组列表是 computed，会自动重算；这里仅刷新时间戳强制图片重新加载
      if (Object.keys(this.rawDirFilePathsMap).length > 0) {
        this.timestamp = new Date().getTime();
      }
    },
  },
  mounted() {
    this.rootUrl = window.location.href;
    if (this.rootUrl.includes("8081") || this.rootUrl.includes("8080")) {
      this.rootUrl = "http://localhost:8003";
    }
    // strip trailing path for production under flask
    try {
      const u = new URL(this.rootUrl);
      if (u.port === '8003' || !u.port) {
        this.rootUrl = u.origin;
      }
    } catch (e) { /* keep as-is */ }

    this.clipboard = new Clipboard(".cb");
    this.clipboard.on('success', (e) => {
      this.$message(`复制成功： ${e.text}`);
      this.clickedImagePath = e.text;
      this.clickedImageName = e.text.split('/').pop();
    });
    this.clipboard.on('error', () => {
      this.$alert('草台，复制失败了');
    });

    window.addEventListener('keydown', this.onGlobalKeydown);
    window.addEventListener('mousemove', this.onNavResizeMove);
    window.addEventListener('mouseup', this.onNavResizeEnd);
  },
  beforeDestroy() {
    window.removeEventListener('keydown', this.onGlobalKeydown);
    window.removeEventListener('mousemove', this.onNavResizeMove);
    window.removeEventListener('mouseup', this.onNavResizeEnd);
    if (this.clipboard) this.clipboard.destroy();
  },
  methods: {
    persistDefaultPrefix() {
      try {
        localStorage.setItem(PREFIX_STORAGE_KEY, this.defaultPrefix || '');
      } catch (e) { /* ignore */ }
    },
    persistNavWidth() {
      try {
        localStorage.setItem(NAV_WIDTH_STORAGE_KEY, String(this.navWidth));
      } catch (e) { /* ignore */ }
    },
    onNavResizeStart() {
      this.navResizing = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
    },
    onNavResizeMove(e) {
      if (!this.navResizing) return;
      this.navWidth = Math.min(NAV_WIDTH_MAX, Math.max(NAV_WIDTH_MIN, e.clientX));
    },
    onNavResizeEnd() {
      if (!this.navResizing) return;
      this.navResizing = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      this.persistNavWidth();
    },
    resolveSrcDir() {
      const raw = (this.srcDir || '').trim();
      if (!raw) return '';
      // 绝对路径或 ~ 开头：不拼前缀
      if (raw.startsWith('/') || raw.startsWith('~')) return raw;
      return joinPrefix(this.defaultPrefix, raw);
    },
    browseDir() {
      const resolvedDir = this.resolveSrcDir();
      if (!resolvedDir) {
        this.$message.warning('请输入目录路径');
        return;
      }
      // 相对路径解析后回填到输入框，方便确认实际路径
      if (resolvedDir !== this.srcDir.trim()) {
        this.srcDir = resolvedDir;
      }
      let formData = new FormData();
      formData.append("recursive", true);
      formData.append("srcDir", resolvedDir);
      formData.append("postfixes", this.checkedPostfixes);
      let srcDirUrl = this.rootUrl + '/getAllImagePaths';
      this.rawDirFilePathsMap = {};
      this.dirLoading = true;
      this.$axios.post(srcDirUrl, formData).then(res => {
        const data = res.data;
        const state = data.state;
        delete data.state;
        if (state == "not exist") {
          this.$message(`目录 ${resolvedDir} 不存在！`);
          return;
        }
        this.rawDirFilePathsMap = data;
        this.timestamp = new Date().getTime();
        this.errInfo = "";
        if (!this.historyDirs.includes(resolvedDir)) {
          this.historyDirs.push(resolvedDir);
        }
      }).catch(reason => {
        console.log(reason);
        this.errInfo = "错误信息：" + reason;
      }).finally(() => {
        this.dirLoading = false;
      });
    },
    RemoveHistoryItem(dir) {
      this.historyDirs.splice(this.historyDirs.indexOf(dir), 1);
    },
    clickHistory(dir) {
      this.srcDir = dir;
      this.browseDir();
    },
    shuffleArray(array) {
      for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
      }
    },
    onPathCopied(path) {
      this.clickedImagePath = path;
      this.clickedImageName = basename(path);
    },
    clearAnnoPending() {
      this.annoPending = null;
    },
    onAnnotateClick(payload) {
      if (!payload || !payload.imagePath) return;
      if (!this.annoPending || this.annoPending.imagePath !== payload.imagePath) {
        this.annoPending = {
          imagePath: payload.imagePath,
          x: payload.x,
          y: payload.y,
          displayX: payload.displayX,
          displayY: payload.displayY,
          naturalWidth: payload.naturalWidth,
          naturalHeight: payload.naturalHeight,
        };
        this.$message(`已选第一点 (${payload.x}, ${payload.y})，再点对角`);
        return;
      }
      const p1 = [this.annoPending.x, this.annoPending.y];
      const p2 = [payload.x, payload.y];
      const dx = Math.abs(p1[0] - p2[0]);
      const dy = Math.abs(p1[1] - p2[1]);
      if (dx < 3 && dy < 3) {
        this.$message.warning("框太小，已忽略");
        this.annoPending = null;
        return;
      }
      const pending = this.annoPending;
      this.annoPending = null;
      this.$axios.post(this.rootUrl + '/saveLabelme', {
        imagePath: pending.imagePath,
        label: (this.annoLabel || "object").trim() || "object",
        points: [p1, p2],
        imageWidth: pending.naturalWidth,
        imageHeight: pending.naturalHeight,
      }).then(res => {
        if (res.data && res.data.state === "ok") {
          this.$message.success(`已保存 ${basename(res.data.jsonPath)}（共 ${res.data.shapeCount} 框）`);
        } else {
          this.$message.error((res.data && res.data.message) || "保存失败");
        }
      }).catch(err => {
        const msg = (err.response && err.response.data && err.response.data.message) || err.message || err;
        this.$message.error("保存失败：" + msg);
      });
    },

    zoomImage(imagePath) {
      if (isPlyPath(imagePath)) {
        this.openPlyModal(imagePath);
        return;
      }
      const idx = this.processedPaths.indexOf(imagePath);
      this.zoomIndex = idx >= 0 ? idx : 0;
      this.zoomedImagePath = imagePath;
      this.resetZoom();
      this.showZoomModal = true;
    },
    openPlyModal(path) {
      if (!path) return;
      this.closeZoomModal();
      this.plyPath = path;
      this.showPlyModal = true;
    },
    closePlyModal() {
      this.showPlyModal = false;
      this.plyPath = "";
    },
    closeZoomModal() {
      this.showZoomModal = false;
      this.zoomedImagePath = "";
      this.showZoomTooltip = false;
      this.zoomPanning = false;
    },
    resetZoom() {
      this.zoomScale = 1;
      this.zoomOffsetX = 0;
      this.zoomOffsetY = 0;
    },
    zoomPrev() {
      if (this.zoomIndex <= 0) return;
      this.zoomIndex -= 1;
      this.zoomedImagePath = this.processedPaths[this.zoomIndex];
      this.resetZoom();
    },
    zoomNext() {
      if (this.zoomIndex >= this.processedPaths.length - 1) return;
      this.zoomIndex += 1;
      this.zoomedImagePath = this.processedPaths[this.zoomIndex];
      this.resetZoom();
    },
    copyZoomedImagePath() {
      const b = document.createElement("button");
      b.setAttribute("class", "cb");
      b.setAttribute("data-clipboard-text", this.zoomedImagePath);
      document.body.appendChild(b);
      b.click();
      b.remove();
    },
    onZoomWheel(e) {
      const factor = e.deltaY < 0 ? 1.15 : 1 / 1.15;
      const next = Math.min(20, Math.max(0.1, this.zoomScale * factor));
      this.zoomScale = next;
    },
    onZoomPanStart(e) {
      if (e.button !== 0) return;
      this.zoomPanning = true;
      this.zoomPanLastX = e.clientX;
      this.zoomPanLastY = e.clientY;
    },
    onZoomPanMove(e) {
      if (!this.zoomPanning) return;
      this.zoomOffsetX += e.clientX - this.zoomPanLastX;
      this.zoomOffsetY += e.clientY - this.zoomPanLastY;
      this.zoomPanLastX = e.clientX;
      this.zoomPanLastY = e.clientY;
    },
    onZoomPanEnd() {
      this.zoomPanning = false;
    },
    onGlobalKeydown(e) {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
      if (e.key === 'Escape') {
        if (this.showPlyModal) {
          this.closePlyModal();
          return;
        }
        if (this.showZoomModal) {
          this.closeZoomModal();
          return;
        }
        if (this.annoPending) {
          this.clearAnnoPending();
          this.$message("已取消标注第一点");
        }
        return;
      }
      if (!this.showZoomModal || this.showPlyModal) return;
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        this.zoomPrev();
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        this.zoomNext();
      } else if (e.key === ' ' || e.code === 'Space') {
        e.preventDefault();
        this.copyZoomedImagePath();
      }
    },
    updateZoomTooltip(e) {
      let oriWidth = e.target.naturalWidth;
      let oriHeight = e.target.naturalHeight;
      if (!oriWidth) return;
      let visWidth = e.target.offsetWidth;
      let visHeight = e.target.offsetHeight;
      let imageRect = e.target.getBoundingClientRect();
      let cursorX = e.clientX - imageRect.x;
      let cursorY = e.clientY - imageRect.y;
      let x = Math.round(cursorX / visWidth * oriWidth);
      let y = Math.round(cursorY / visHeight * oriHeight);
      this.zoomTooltipContent = `${this.zoomedImagePath}\n坐标: (${x}, ${y}) | 比例: (${(x / oriWidth * 100).toFixed(1)}%, ${(y / oriHeight * 100).toFixed(1)}%) | 尺寸: ${oriWidth} × ${oriHeight} | 缩放: ${this.zoomScale.toFixed(2)}x`;
      this.showZoomTooltip = true;
      this.$refs.zoomTooltip.style.top = `${e.clientY + 10}px`;
      this.$refs.zoomTooltip.style.left = `${e.clientX + 10}px`;
    },
    closeZoomTooltip() {
      this.showZoomTooltip = false;
    },
  }
}
</script>

<style lang="less">
html, body, #app {
  background-color: #C7EDCC;
  min-height: 100%;
}

.postfixes {
  display: grid;
  grid-template-columns: auto auto;
  border: #42b983;
  border-radius: 5px;
  border-style: dotted;
}

nav {
  text-align: left;
  display: flex;
  flex-direction: column;
  background-color: antiquewhite;
  width: 20rem;
  left: 0;
  top: 0;
  bottom: 0;
  position: fixed;
  z-index: 2;
  padding: 1rem;
  overflow-x: hidden;
  overflow-y: auto;

  >* {
    margin: 0.5rem 0;
  }
}

.nav-resize {
  position: absolute;
  top: 0;
  right: 0;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  margin: 0 !important;
  z-index: 3;
  background: transparent;

  &:hover,
  &:active {
    background: rgba(66, 185, 131, 0.35);
  }
}

main {
